"""Voronoi-guided circle packing optimization for n=26 circles in unit square"""
import numpy as np
from scipy.optimize import minimize
from scipy.spatial import Voronoi


def _clip_halfplane(polygon, test_func):
    """Clip polygon against a halfplane defined by test function using Sutherland-Hodgman."""
    if len(polygon) == 0:
        return np.array([]).reshape(0, 2)

    result = []
    n = len(polygon)

    for i in range(n):
        curr = polygon[i]
        prev = polygon[(i - 1) % n]

        curr_in = test_func(curr)
        prev_in = test_func(prev)

        if curr_in:
            if not prev_in:
                intersection = _find_intersection(prev, curr, test_func)
                result.append(intersection)
            result.append(curr)
        elif prev_in:
            intersection = _find_intersection(prev, curr, test_func)
            result.append(intersection)

    return np.array(result) if result else np.array([]).reshape(0, 2)


def _find_intersection(p1, p2, test_func):
    """Find intersection point between line segment p1-p2 and halfplane boundary."""
    # Linear interpolation to find boundary crossing
    t = 0.5
    for _ in range(20):
        mid = (p1 + p2) / 2
        if test_func(mid):
            p1 = mid
        else:
            p2 = mid
    return (p1 + p2) / 2


def clip_polygon_to_square(polygon):
    """Clip polygon vertices to unit square using Sutherland-Hodgman algorithm."""
    if len(polygon) == 0:
        return np.array([]).reshape(0, 2)

    result = polygon.copy()
    result = _clip_halfplane(result, lambda p: p[0] >= 0)
    result = _clip_halfplane(result, lambda p: p[0] <= 1)
    result = _clip_halfplane(result, lambda p: p[1] >= 0)
    result = _clip_halfplane(result, lambda p: p[1] <= 1)

    return result if len(result) > 0 else np.array([]).reshape(0, 2)


def point_to_segment_distance(point, p1, p2):
    """Compute distance from point to line segment p1-p2."""
    segment = p2 - p1
    point_vec = point - p1

    denom = np.dot(segment, segment)
    if denom < 1e-12:
        return np.linalg.norm(point - p1)

    t = np.dot(point_vec, segment) / denom
    t = max(0, min(1, t))
    closest = p1 + t * segment

    return np.linalg.norm(point - closest)


def compute_inradius(center, polygon):
    """Compute inradius (minimum distance from center to polygon edges)."""
    if len(polygon) < 3:
        return 0.0

    min_dist = float('inf')
    n = len(polygon)

    for i in range(n):
        p1 = polygon[i]
        p2 = polygon[(i + 1) % n]
        dist = point_to_segment_distance(center, p1, p2)
        min_dist = min(min_dist, dist)

    return min_dist


def compute_voronoi_radii(centers):
    """
    Compute Voronoi-based radii for given centers.
    For each center, find the inradius of its Voronoi cell clipped to unit square.
    Infinite regions fall back to boundary distance.
    """
    n = centers.shape[0]
    radii = np.zeros(n)

    try:
        vor = Voronoi(centers)
    except Exception:
        for i in range(n):
            x, y = centers[i]
            radii[i] = min(x, y, 1 - x, 1 - y)
        return radii

    for i in range(n):
        region_idx = vor.point_region[i]
        region = vor.regions[region_idx]

        if -1 in region or len(region) < 3:
            x, y = centers[i]
            radii[i] = min(x, y, 1 - x, 1 - y)
            continue

        region_vertices = vor.vertices[region]
        clipped = clip_polygon_to_square(region_vertices)

        if len(clipped) >= 3:
            radii[i] = compute_inradius(centers[i], clipped)
        else:
            x, y = centers[i]
            radii[i] = min(x, y, 1 - x, 1 - y)

    return radii


def construct_packing():
    """
    Construct circle packing using Voronoi-guided optimization.

    Two-stage approach:
    1. Voronoi-based: Optimize center positions to maximize sum of Voronoi inradii
       using COBYLA (derivative-free, handles non-smooth Voronoi objective)
    2. SLSQP refinement: Optimize both centers and radii with explicit constraints
       to ensure all constraints are strictly satisfied

    Returns:
        Tuple of (centers, radii, sum_of_radii)
    """
    n = 26

    # Initial hexagonal lattice configuration
    rows = [6, 5, 6, 5, 4]
    base_r = 0.09

    centers = []
    for row_idx, n_circles in enumerate(rows):
        y = base_r + row_idx * base_r * np.sqrt(3)
        for col_idx in range(n_circles):
            x = base_r + col_idx * 2 * base_r
            if row_idx % 2 == 1:
                x += base_r
            centers.append([x, y])

    centers = np.array(centers)

    # Stage 1: Voronoi-based optimization using COBYLA
    def voronoi_objective(x):
        centers_opt = x.reshape(n, 2)
        centers_opt = np.clip(centers_opt, 0.01, 0.99)
        radii = compute_voronoi_radii(centers_opt)
        return -np.sum(radii)

    x0 = centers.flatten()

    # COBYLA doesn't support bounds, so we use constraints
    constraints_vor = []
    for i in range(n):
        constraints_vor.append({'type': 'ineq', 'fun': lambda x, i=i: x[2*i] - 0.01})
        constraints_vor.append({'type': 'ineq', 'fun': lambda x, i=i: 0.99 - x[2*i]})
        constraints_vor.append({'type': 'ineq', 'fun': lambda x, i=i: x[2*i+1] - 0.01})
        constraints_vor.append({'type': 'ineq', 'fun': lambda x, i=i: 0.99 - x[2*i+1]})

    result_vor = minimize(
        voronoi_objective, x0, method='COBYLA',
        constraints=constraints_vor,
        options={'maxiter': 200, 'rhobeg': 0.01, 'disp': False}
    )

    centers_opt = result_vor.x.reshape(n, 2)
    radii = compute_voronoi_radii(centers_opt)

    # Stage 2: SLSQP refinement with explicit constraints
    def boundary_constraints(x):
        centers_opt = x[:2*n].reshape(n, 2)
        radii_opt = x[2*n:]
        cons = []
        for i in range(n):
            cx, cy = centers_opt[i]
            r = radii_opt[i]
            cons.extend([cx - r, 1 - cx - r, cy - r, 1 - cy - r])
        return np.array(cons)

    def overlap_constraints(x):
        centers_opt = x[:2*n].reshape(n, 2)
        radii_opt = x[2*n:]
        cons = []
        for i in range(n):
            for j in range(i+1, n):
                dist = np.sqrt(np.sum((centers_opt[i] - centers_opt[j])**2))
                cons.append(dist - radii_opt[i] - radii_opt[j])
        return np.array(cons)

    def objective(x):
        return -np.sum(x[2*n:])

    x0_refine = np.concatenate([centers_opt.flatten(), radii])
    bounds_refine = [(0.01, 0.99)] * (2*n) + [(0.01, 0.5)] * n

    constraints = [
        {'type': 'ineq', 'fun': boundary_constraints},
        {'type': 'ineq', 'fun': overlap_constraints}
    ]

    result_refine = minimize(
        objective, x0_refine, method='SLSQP', bounds=bounds_refine,
        constraints=constraints,
        options={'maxiter': 300, 'ftol': 1e-12, 'disp': False}
    )

    centers_final = result_refine.x[:2*n].reshape(n, 2)
    radii_final = result_refine.x[2*n:]
    radii_final = np.maximum(radii_final, 0.01)

    # Fix any constraint violations
    for i in range(n):
        cx, cy = centers_final[i]
        r = radii_final[i]
        if cx - r < 0:
            centers_final[i, 0] = r
        if cx + r > 1:
            centers_final[i, 0] = 1 - r
        if cy - r < 0:
            centers_final[i, 1] = r
        if cy + r > 1:
            centers_final[i, 1] = 1 - r

    sum_radii = np.sum(radii_final)

    return centers_final, radii_final, sum_radii


def compute_max_radii(centers):
    """
    Compute maximum radii for each circle based on constraints.
    Kept for compatibility with visualization.
    """
    n = centers.shape[0]
    radii = np.zeros(n)

    for i in range(n):
        x, y = centers[i]
        max_r = min(x, y, 1 - x, 1 - y)

        for j in range(n):
            if i != j:
                dist = np.sqrt(np.sum((centers[i] - centers[j]) ** 2))
                max_r = min(max_r, dist / 2)

        radii[i] = max_r

    return radii


